functions.code:
let add x y = x + y

(* Recursive function *)
let rec factorial n =
  if n = 0 then 1 else n * factorial (n - 1)

(* Anonymous function *)
let multiply = fun x y -> x * y

error_handling.code:
(* Exceptions *)
exception DivByZero

let div x y = 
  if y = 0 then raise DivByZero else x / y

let safe = 
  try div 10 0 
  with DivByZero -> 0

(* Option type *)
let safe_div x y =
  if y = 0 then None else Some (x / y)
